cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./mcpserver) || exit 1; for i in $I; do case $i in context|crypto/subtle|encoding/json|errors|fmt|net/http|slices|strings|github.com/modelcontextprotocol/go-sdk/mcp|morphstudio/control|morphstudio/queue) ;; *) echo "imports: package mcpserver imports $i (allowed: context, crypto/subtle, encoding/json, errors, fmt, net/http, slices, strings, github.com/modelcontextprotocol/go-sdk/mcp, morphstudio/control, morphstudio/queue)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' mcpserver/pm.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' mcpserver/pm.go 2>&1); [ -z "$C" ] || { echo "clock: mcpserver/pm.go reads time.Now or time.Since (package mcpserver reads no clock)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" mcpserver/pm.go 2>&1); [ -z "$C" ] || { echo "net: mcpserver/pm.go uses $x (no HTTP client and never a listener in package mcpserver)"; exit 1; }; done

